/**
 * What a customer pays for a repair, as the server works it out for each
 * provider and part grade (repair providers list → `bill`), for the website and
 * the app alike. The server builds the bill with the booking's own price
 * function, so the card, the confirm screen and the final bill are one number.
 */

/**
 * The price chosen with this provider: the grade the customer picked, else the provider's own.
 * @param {any} provider
 * @param {string | null | undefined} [qualityCode]
 */
export function chosenPrice(provider, qualityCode) {
  if (!provider) return { pricePaise: null, bill: null };
  const grade = (provider.priceOptions || []).find((o) => (o.qualityCode || null) === (qualityCode || null));
  const src = grade || provider;
  return { pricePaise: src.totalPaise ?? null, bill: src.bill || null };
}

/** The total to show: the server's full bill when it has one, else the bare price. */
export const totalOf = ({ pricePaise, bill }) => (bill?.totalPaise ?? pricePaise ?? null);

/**
 * What the bill adds on top of the repair, the way delivery apps show it: one
 * fee line (journey, platform fee, any small-job top-up together, never the
 * kilometres) and taxes. Providers and admin still see the full breakdown.
 */
export function billExtras(bill) {
  if (!bill) return [];
  const journeyPaise = (bill.travelPaise || 0) + (bill.pickupPaise || 0) + (bill.returnPaise || 0);
  const feePaise = journeyPaise + (bill.smallJobPaise || 0) + (bill.platformFeePaise || 0);
  return [
    [feeLabel(bill), feePaise],
    [`Waiting at your door${bill.waitingMin ? ` (${bill.waitingMin} min)` : ''}`, bill.waitingPaise],
    ['Taxes', bill.taxPaise],
  ].filter(([, paise]) => paise > 0).map(([label, paise]) => ({ label, paise }));
}

/** The one fee line's name, from what is in it. */
export function feeLabel(b = {}) {
  if ((b.pickupPaise || 0) + (b.returnPaise || 0) > 0) return 'Pickup, return & service fee';
  return b.travelPaise > 0 ? 'Visit & service fee' : 'Service fee';
}

/** Nearby enough that the visit costs nothing: worth saying ("Free visit"). */
export const freeVisit = (bill, serviceMode) => !!bill && ['doorstep', 'roadside'].includes(serviceMode) && !bill.travelPaise;

/** How far the pro is, what the visit costs, and the waiting rule, for a doorstep job ("Your pro is 2.4 km away. The visit is free. Free waiting for 10 min…"). */
export function visitNote(bill, serviceMode, pro = 'pro') {
  if (!bill || !['doorstep', 'roadside'].includes(serviceMode)) return null;
  const parts = [];
  const km = Number(bill.distanceKm);
  if (bill.distanceKm != null && Number.isFinite(km)) {
    const away = km < 1 ? 'less than 1 km away' : `${km.toFixed(1)} km away`;
    parts.push(`Your ${pro} is ${away}. ${bill.travelPaise > 0 ? `Their travel is in the fee above${bill.trafficHours ? ', at the traffic-hours rate' : ''}.` : 'The visit is free.'}`);
  }
  const w = bill.waitRule;
  if (w?.perMinPaise > 0) parts.push(`Free waiting for ${w.freeMin} min at your door, then ₹${w.perMinPaise / 100} a minute${w.maxPaise > 0 ? ` (at most ₹${w.maxPaise / 100})` : ''}.`);
  return parts.length ? parts.join(' ') : null;
}

/** The bill's words in the service's own terms (repairBasket termsOf): a class is not a repair and has no parts. */
export function billWords(terms = {}) {
  const job = terms.job || 'repair';
  const pro = terms.pro || 'technician';
  return {
    base: `for the ${job}, plus:`,
    includes: terms.packaged
      ? 'Includes taxes. This is the price you pay - nothing is added later without your approval.'
      : 'Includes parts, labour and taxes. This is the price you pay - nothing is added later without your approval.',
    cash: (inspection) => `Pay the ${pro} directly once the ${inspection ? 'inspection' : job} is done.`,
  };
}

/**
 * The wait at the door right now, from the rule frozen on the booking (server lifecycle freezeWaiting does the same sums), or null when there is nothing to show.
 * @param {any} booking
 * @param {number} [now]
 */
export function waitingNow(booking, now = Date.now()) {
  const rule = booking?.priceSnapshot?.waitRule;
  if (!rule?.perMinPaise || booking.status !== 'ARRIVED' || booking.paymentStatus === 'paid') return null;
  const at = [...(booking.statusHistory || [])].reverse().find((h) => h.status === 'ARRIVED')?.at;
  if (!at) return null;
  const stoppedAt = booking.otpVerified?.startAt ? new Date(booking.otpVerified.startAt).getTime() : null;
  const sec = Math.max(0, Math.floor(((stoppedAt ?? now) - new Date(at).getTime()) / 1000));
  const billableMin = Math.max(0, Math.floor(sec / 60) - rule.freeMin);
  const raw = billableMin * rule.perMinPaise;
  return {
    freeLeftSec: Math.max(0, rule.freeMin * 60 - sec),
    billableMin,
    paise: rule.maxPaise > 0 ? Math.min(raw, rule.maxPaise) : raw,
    capped: rule.maxPaise > 0 && raw >= rule.maxPaise,
    rule,
    stopped: stoppedAt != null,
  };
}

/** Seconds as m:ss for a countdown. */
export const mmss = (sec) => `${Math.floor(sec / 60)}:${String(sec % 60).padStart(2, '0')}`;
